uint64_t bits_of(double d) {
  uint64_t b;
  std::memcpy(&b, &d, sizeof b);
  return b;
}

unsigned flags_of(const GTEXT_CSS_Component_Value & v) {
  return ((v.flags & GTEXT_CSS_FLAG_NUMBER_INEXACT) ? 1u : 0u) | ((v.flags & GTEXT_CSS_FLAG_NUMBER_OVERFLOW) ? 2u : 0u) |
         ((v.flags & GTEXT_CSS_FLAG_NUMBER_UNDERFLOW) ? 4u : 0u);
}

void check_rows(const char * unit) {
  size_t n = 0;
  for (const NumberRow & row : kNumberRows) {
    const std::string css = std::string(row.spelling) + unit;
    Parsed p;
    parse_into(p, gtext_css_parse_component_values, css);
    ASSERT_EQ(p.status, GTEXT_CSS_OK) << row.spelling;
    ASSERT_EQ(p.tree->value_count, 1u) << "one numeric token: " << row.spelling;
    const GTEXT_CSS_Component_Value & v = p.tree->values[0];
    const std::string repr(v.repr.data, v.repr.length);
    EXPECT_EQ(repr, row.spelling) << "the spelling is kept as written";
    EXPECT_EQ(bits_of(v.number), row.bits) << row.spelling << unit << ": got " << std::hexfloat << v.number;
    EXPECT_EQ(flags_of(v), row.flags) << row.spelling << unit;
    EXPECT_EQ(v.flags & GTEXT_CSS_FLAG_UNCLOSED, 0u);
    n++;
  }
  EXPECT_GT(n, 250u);
}

TEST(CssNumbers, EveryNumberIsTheNearestDoubleAndSaysWhenItIsNot) {
  check_rows("");
}

TEST(CssNumbers, SoAreDimensionsAndPercentages) {
  check_rows("px");
  check_rows("%");
}

TEST(CssNumbers, NoRoundingModeOrFlagOfTheHostChangesOne) {
  const int saved = std::fegetround();
  for (const int mode : {FE_UPWARD, FE_DOWNWARD, FE_TOWARDZERO, FE_TONEAREST}) {
    ASSERT_EQ(std::fesetround(mode), 0);
    check_rows("");
  }
  std::fesetround(saved);
}

TEST(CssNumbers, TheExamplesOfTheSpec) {
  struct E {
    const char * css;
    double value;
    unsigned flags;
    bool integer;
  };
  const E examples[] = {
      {"1e400", 1.0 / 0.0, 3u, false},
      {"-1e400", -1.0 / 0.0, 3u, false},
      {"1.5e-320", 1.5e-320, 5u, false},
      {"0.1", 0.1, 1u, false},
      {"0.5", 0.5, 0u, false},
      {"16777217", 16777217.0, 0u, true},
      {"100000000000000000000000", 1e23, 1u, true},
  };
  for (const E & e : examples) {
    Parsed p;
    parse_into(p, gtext_css_parse_component_values, e.css);
    ASSERT_EQ(p.status, GTEXT_CSS_OK) << e.css;
    ASSERT_EQ(p.tree->value_count, 1u);
    EXPECT_EQ(p.tree->values[0].number, e.value) << e.css;
    EXPECT_EQ(flags_of(p.tree->values[0]), e.flags) << e.css;
    EXPECT_EQ((p.tree->values[0].flags & GTEXT_CSS_FLAG_INTEGER) != 0, e.integer) << e.css;
  }
}

TEST(CssNumbers, ALongSpellingIsRoundedAsExactlyAsAShortOne) {
  // 800 digits: "1" and 799 zeros is 1e799 (overflow), "0." and 799 zeros and a 1 is 1e-800 (underflow to 0), and a
  // 400-digit number that is exactly a double (2^1000) is exact however many zeros follow the digits.
  Parsed a;
  parse_into(a, gtext_css_parse_component_values, "1" + std::string(799, '0'));
  EXPECT_EQ(a.tree->values[0].number, 1.0 / 0.0);
  Parsed b;
  parse_into(b, gtext_css_parse_component_values, "0." + std::string(799, '0') + "1");
  EXPECT_EQ(b.tree->values[0].number, 0.0);
  EXPECT_NE(b.tree->values[0].flags & GTEXT_CSS_FLAG_NUMBER_UNDERFLOW, 0u);
  Parsed c;
  const std::string two1000 =
      "";
  parse_into(c, gtext_css_parse_component_values, two1000 + std::string(400, '0') + "e-400");
  EXPECT_EQ(c.tree->values[0].number, std::ldexp(1.0, 1000));
  EXPECT_EQ(flags_of(c.tree->values[0]), 0u);
  // And one that is a tie to the last digit: 2^53 + 1 then 600 zeros of padding after the point.
  Parsed d;
  parse_into(d, gtext_css_parse_component_values, "9007199254740993." + std::string(600, '0'));
  // (a "." followed by digits is a decimal; the tie goes to the even neighbour)
  EXPECT_EQ(d.tree->values[0].number, 9007199254740992.0);
  Parsed e;
  parse_into(e, gtext_css_parse_component_values, "9007199254740993." + std::string(600, '0') + "1");
  EXPECT_EQ(e.tree->values[0].number, 9007199254740994.0) << "a hair over the tie goes up";
}

// ---- CSSOM's spelling -----------------------------------------------------------------------------------------

std::string cssom_written(const std::string & css) {
  Parsed p;
  parse_into(p, gtext_css_parse_component_values, css);
  if (p.status != GTEXT_CSS_OK) {
    return "?";
  }
  GTEXT_CSS_Serialize_Options so = gtext_css_serialize_options_default();
  so.numbers = GTEXT_CSS_NUMBERS_CSSOM;
  return serialize(p.tree, &so);
}

TEST(CssNumbers, CssomWritesTheShortestDigitsInFixedNotationRoundedToSixDecimals) {
  for (const CssomRow & row : kCssomRows) {
    EXPECT_EQ(cssom_written(row.spelling), row.written) << row.spelling;
  }
}

TEST(CssNumbers, CssomPercentagesAndDimensionsAndTheSpellingsItHasToChoose) {
  EXPECT_EQ(cssom_written("12.50%"), "12.5%");
  EXPECT_EQ(cssom_written("1e1px"), "10px");
  EXPECT_EQ(cssom_written("0.0000004em"), "0em");
  EXPECT_EQ(cssom_written("-0.0000004em"), "0em") << "never negative zero";
  EXPECT_EQ(cssom_written("-0"), "0");
  EXPECT_EQ(cssom_written("+7"), "7");
  // No token has a NaN, and an infinity (an overflowed number) is written as the largest double, as digits.
  const std::string inf = cssom_written("1e400");
  EXPECT_EQ(inf.substr(0, 17), "17976931348623157");
  EXPECT_EQ(inf.size(), 309u);
  EXPECT_EQ(cssom_written("-1e400"), "-" + inf);
  // A second serialization of the written text reads back as the same number to six decimals.
  EXPECT_EQ(cssom_written(cssom_written("0.1234565")), cssom_written("0.1234565"));
}

